UPLOAD_DIR = Path("/srv/uploads")
MAX_UPLOAD_BYTES = 10 * 1024 * 1024


def read_upload(name: str) -> bytes:
    '''Return the contents of the uploaded file with this name, as sent by the client.

    Raises ValueError if the name is invalid, is a symbolic link, resolves outside the upload directory, or the file exceeds MAX_UPLOAD_BYTES. Raises FileNotFoundError, IsADirectoryError or PermissionError if the file cannot be read.
    '''
    base = UPLOAD_DIR.resolve()
    try:
        is_link = (base / name).is_symlink()
        path = (base / name).resolve()
    except (ValueError, OSError):
        raise ValueError('invalid file name') from None
    if is_link:
        raise ValueError('symbolic links are not allowed')
    if not path.is_relative_to(base):
        raise ValueError('file name escapes the upload directory')
    try:
        with path.open('rb') as handle:
            data = handle.read(MAX_UPLOAD_BYTES + 1)
    except FileNotFoundError:
        raise FileNotFoundError('no upload with this name') from None
    except IsADirectoryError:
        raise IsADirectoryError('upload name is a directory') from None
    except PermissionError:
        raise PermissionError('upload cannot be read') from None
    if len(data) > MAX_UPLOAD_BYTES:
        raise ValueError('upload exceeds the size limit')
    return data

