import operator

MAX_EXPRESSION_LENGTH = 1000
MAX_MAGNITUDE = 10 ** 300

# Only these operators are allowed. ** is excluded because very large exponents can exhaust CPU and memory.
_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
}
_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


def _check_magnitude(value: float) -> None:
    '''Reject values whose magnitude exceeds MAX_MAGNITUDE, including infinity.'''
    if abs(value) > MAX_MAGNITUDE:
        raise ValueError('number is too large')


def _eval_node(node: ast.AST) -> float:
    '''Recursively evaluate a whitelisted AST node.'''
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
        _check_magnitude(node.value)
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in _BIN_OPS:
        result = _BIN_OPS[type(node.op)](_eval_node(node.left), _eval_node(node.right))
        _check_magnitude(result)
        return result
    if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY_OPS:
        return _UNARY_OPS[type(node.op)](_eval_node(node.operand))
    raise ValueError('unsupported expression')


