    '''Evaluate an arithmetic expression typed by the user, such as 2 * (3 + 4).

    Only numeric literals, parentheses, unary plus and minus, and the operators
    + - * / // % are accepted. The expression may be at most 1000 characters long,
    and every operand and intermediate result must have magnitude at most 10**300.
    Anything else raises ValueError.

    Raises:
        SyntaxError: if the expression is not valid Python syntax.
        ValueError: if the expression is too long, contains unsupported constructs,
            or has a value whose magnitude is too large.
        ZeroDivisionError: if the expression divides by zero.
    '''
    source = expression.strip()
    if len(source) > MAX_EXPRESSION_LENGTH:
        raise ValueError('expression is too long')
    tree = ast.parse(source, mode='eval')
    return float(_eval_node(tree))

